�# 水光独立产品约束

- 只在本目录开发。父目录02_开发代码是只读来源，不是运行依赖。
- 入口调用链：界面/CLI → pipeline → preprocess/detectors → results；检测器不得导入界面或pipeline。
- 八项：pores/texture/spots/brown/redness/vascular/acne/surface_gloss。
- 无紫区、皱纹、报告评分、四光源、Celery、OSS及下载模型的运行路径。
- 保持SHA来源清单；迁入算法先验证，再仅修改必要可见域/运行设备接线。
- 使用父项目共享虚拟环境；所有其他文件和缓存局限水光目录。禁止自动下载/升级依赖。
- 图像问题定位不是注射或微晶操作安全判定，不输出操作点、深度、剂量。
- 每个实质检查点更新父目录水光技术总账，不写入V2/V3台账。
- 最新验收输入为用户提供的one/two两套RGB三视图，仅此6张，不扩大旧图库。
from pathlib import Path
import json, re
from PIL import Image
from .config import VIEWS
from .io import sha256, read_image

def load_capture(manifest):
 path=Path(manifest).resolve()
 data=json.loads(path.read_text(encoding="utf-8"))
 if data.get("schema_version") != "shuiguang_capture_v1": raise ValueError("不支持的三视图清单版本")
 if data.get("modality","RGB") != "RGB": raise ValueError("本项目只支持RGB")
 if set(data.get("views",{})) != set(VIEWS): raise ValueError("必须提供左侧、正面、右侧三张图")
 sid=str(data.get("capture_id",""))
 if not re.fullmatch(r"[\w-]{1,80}",sid): raise ValueError("采集编号仅允许文字、数字、下划线和短横线")
 loaded={}
 for view in VIEWS:
  item=dict(data["views"][view])
  if item.get("modality","RGB")!="RGB": raise ValueError("不接受混合光源")
  source=(path.parent/item["path"]).resolve()
  if not source.is_file(): raise ValueError(f"{view}原图不存在")
  actual=sha256(source)
  if item.get("sha256") and item["sha256"]!=actual: raise ValueError(f"{view}原图SHA不一致")
  if type(item.get("mirrored",False)) is not bool: raise ValueError("mirrored必须为布尔值")
  with Image.open(source) as im:
   if im.mode not in {"RGB","RGBA"}: raise ValueError("需要彩色RGB照片，不接受灰度图")
  image=read_image(source,item.get("mirrored",False))
  loaded[view]={**item,"source":source,"sha256":actual,"image":image}
 if len({v["sha256"] for v in loaded.values()})!=3: raise ValueError("三视图不能重复使用同一图片")
 return data,loaded

def folder_manifest(folder,capture_id=None):
 folder=Path(folder).resolve()
 views={}
 for view,name in zip(VIEWS,("RGB_L.jpg","RGB_M.jpg","RGB_R.jpg")):
  p=folder/name
  if not p.is_file(): raise ValueError(f"缺少{name}")
  item={"path":name,"sha256":sha256(p),"mirrored":False,"capture_method":"manual_import"}
  sidecars=[p.with_suffix(".json"),p.with_suffix(p.suffix+".json")]
  present=[m for m in sidecars if m.is_file()]
  if len(present)>1: raise ValueError("同一照片存在两份拍照元数据，需明确保留一份")
  if present:
   metadata=json.loads(present[0].read_text(encoding="utf-8"))
   for key in ("frame_id","timestamp","capture_time","raw_pose","pose","config","stable","mirrored"):
    if key in metadata: item[key]=metadata[key]
   item["capture_method"]="auto_capture_metadata"
   item["capture_metadata_sha256"]=sha256(present[0])
  views[view]=item
 return {"schema_version":"shuiguang_capture_v1","capture_id":capture_id or folder.name,
         "subject_id":capture_id or folder.name,"modality":"RGB","views":views}
"""Loopback-only local service. One worker owns the reusable model session."""
import argparse, base64, json, threading, uuid
from pathlib import Path
from concurrent.futures import ThreadPoolExecutor
from fastapi import FastAPI, Request, HTTPException
from fastapi.responses import FileResponse
import uvicorn
from shuiguang.config import ROOT,VIEWS
from shuiguang.io import write_json,read_image,sha256

app=FastAPI(docs_url=None,redoc_url=None)
executor=ThreadPoolExecutor(max_workers=1)
lock=threading.Lock();jobs={};session=None;device="cpu";busy=False

def work(job_id,manifest):
 global session,busy
 try:
  from shuiguang.capture import load_capture
  load_capture(manifest)
  if session is None:
   from shuiguang.runtime import configure
   configure(device)
   from shuiguang.pipeline import AnalysisSession
   session=AnalysisSession(device)
  def progress(event): jobs[job_id]["progress"]=event
  result,status=session.analyze(manifest,ROOT/"outputs",progress)
  jobs[job_id].update(status="complete",analysis_status=status,base="/results/"+result.name+"/")
 except Exception as exc:
  write_json(ROOT/"runtime/jobs"/job_id/"error.json",{"type":type(exc).__name__,"message":str(exc)})
  jobs[job_id].update(status="failed",message="检测未完成，请核对输入或查看运行回执")
 finally:
  with lock: busy=False

@app.get("/health")
def health():
 return {"status":"ok","product":"shuiguang","version":"0.0.1","device":device,"busy":busy}

@app.post("/api/jobs",status_code=202)
async def submit(request:Request):
 global busy
 if request.headers.get("content-type","").split(";")[0]!="application/json": raise HTTPException(415,"需要JSON三视图")
 size=request.headers.get("content-length")
 if not size or not size.isdigit() or int(size)>52*1024*1024: raise HTTPException(413,"上传大小超限")
 with lock:
  if busy: raise HTTPException(409,"已有检测任务正在运行")
  busy=True
 jid=uuid.uuid4().hex
 try:
  body=await request.body()
  if len(body)>52*1024*1024: raise ValueError("上传大小超限")
  data=json.loads(body)
  if set(data.get("views",{}))!=set(VIEWS): raise ValueError("需要三张RGB照片")
  folder=ROOT/"runtime/jobs"/jid;folder.mkdir(parents=True)
  manifest={"schema_version":"shuiguang_capture_v1","capture_id":jid,"subject_id":"","modality":"RGB","views":{}}
  hashes=[]
  for view in VIEWS:
   encoded=data["views"][view]["data"]
   if len(encoded)>17*1024*1024: raise ValueError("单图超限")
   content=base64.b64decode(encoded,validate=True)
   p=folder/(view+".jpg");p.write_bytes(content)
   read_image(p)
   digest=sha256(p);hashes.append(digest)
   manifest["views"][view]={"path":p.name,"sha256":digest,"mirrored":False,"capture_method":"manual_upload"}
  if len(set(hashes))!=3: raise ValueError("不能重复使用同一照片")
  path=folder/"capture.json";write_json(path,manifest)
  jobs[jid]={"id":jid,"status":"running","progress":{"completed":0,"total":24}}
  executor.submit(work,jid,path)
  return {"id":jid}
 except Exception as exc:
  with lock: busy=False
  raise HTTPException(400,"输入无效：需要三张不同的可读取RGB照片") from exc

@app.get("/api/jobs/{job_id}")
def status(job_id:str):
