import os,time
LOCK_EX=2
def flock(fd,operation):
    fd=fd.fileno() if hasattr(fd,'fileno') else fd
    if operation!=LOCK_EX:raise ValueError("Only exclusive locking is supported")
    if os.name!="nt":
        import fcntl
        return fcntl.flock(fd,fcntl.LOCK_EX)
    import msvcrt
    if os.fstat(fd).st_size==0:os.write(fd,b"\0")
    deadline=time.monotonic()+15
    while True:
        os.lseek(fd,0,os.SEEK_SET)
        try:return msvcrt.locking(fd,msvcrt.LK_NBLCK,1)
        except OSError:
            if time.monotonic()>=deadline:raise TimeoutError("Collector lock busy")
