import os,hashlib
from contextlib import contextmanager
@contextmanager
def exclusive(path):
    if os.name!="nt":
        import fcntl
        with path.open("a+b") as file:
            fcntl.flock(file,fcntl.LOCK_EX)
            yield
        return
    import ctypes
    from ctypes import wintypes
    kernel=ctypes.WinDLL("kernel32",use_last_error=True)
    kernel.CreateMutexW.argtypes=[ctypes.c_void_p,wintypes.BOOL,wintypes.LPCWSTR]
    kernel.CreateMutexW.restype=wintypes.HANDLE
    kernel.WaitForSingleObject.argtypes=[wintypes.HANDLE,wintypes.DWORD]
    kernel.WaitForSingleObject.restype=wintypes.DWORD
    kernel.ReleaseMutex.argtypes=[wintypes.HANDLE]
    kernel.CloseHandle.argtypes=[wintypes.HANDLE]
    name="Local\\OpenvelaCollector_"+hashlib.sha256(os.path.normcase(str(path.resolve())).encode()).hexdigest()[:24]
    handle=kernel.CreateMutexW(None,False,name)
    if not handle:raise ctypes.WinError(ctypes.get_last_error())
    acquired=False
    try:
        result=kernel.WaitForSingleObject(handle,15000)
        if result not in (0,128):raise TimeoutError("Collector mutex busy")
        acquired=True
        yield
    finally:
